import { type ReactNode, useState } from 'react';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import {
  Activity, ArrowRight, Bell, CalendarDays, Check, ChevronRight, CircleAlert, ClipboardList,
  Clock3, CreditCard, Droplets, Home, Leaf, LocateFixed, LogOut, MapPin, Menu,
  RefreshCw, Search, ShieldCheck, Sprout, Tractor, TrendingUp, UserRound, Users,
  X, IndianRupee, Phone, BarChart3
} from 'lucide-react';
import {
  getGetBookingQueryKey, getGetDashboardQueryKey, getGetProfileQueryKey,
  getGetOfficerDashboardQueryKey, getGetAdminDashboardQueryKey, getListBookingsQueryKey,
  getListCentreSlotsQueryKey, getListCentresQueryKey, getListPaymentsQueryKey,
  getListNotificationsQueryKey, useCancelBooking, useCreateBooking, useDemoLogin,
  useGetAdminDashboard, useGetBooking, useGetDashboard, useGetOfficerDashboard,
  useGetProfile, useListBookings, useListCentreSlots, useListCentres, useListNotifications,
  useListPayments, useMarkNotificationRead, useUpdateBooking, useUpdateProfile
} from '@workspace/api-client-react';
import type { ProcurementCentre, Slot } from '@workspace/api-client-react';
import { Link, Route, Switch, useLocation } from 'wouter';
import { ErrorBoundary } from '@/components/error-boundary';
import { Toaster } from '@/components/ui/toaster';
import { TooltipProvider } from '@/components/ui/tooltip';

const queryClient = new QueryClient();
type Role = 'farmer' | 'officer' | 'admin';

const formatDate = (value?: string) => value ? new Date(value).toLocaleDateString('en-IN', { day: 'numeric', month: 'short', year: 'numeric' }) : '—';
const money = (value?: number) => `₹${(value ?? 0).toLocaleString('en-IN')}`;
const titleCase = (value = '') => value.charAt(0).toUpperCase() + value.slice(1);

function LoadingState({ rows = 3 }: { rows?: number }) {
  return <div className="space-y-3" data-testid="state-loading">{Array.from({ length: rows }).map((_, i) => <div key={i} className="skeleton h-16 w-full" />)}</div>;
}
function ErrorState({ onRetry }: { onRetry?: () => void }) {
  return <div className="card flex flex-col items-center justify-center gap-3 p-10 text-center" data-testid="state-error"><CircleAlert className="h-8 w-8 text-destructive" /><div><p className="font-bold">We could not load this view</p><p className="mt-1 text-sm text-muted-foreground">Check your connection and try again.</p></div>{onRetry && <button className="btn btn-outline" onClick={onRetry} data-testid="button-retry"><RefreshCw className="h-4 w-4" /> Try again</button>}</div>;
}
function EmptyState({ title, text }: { title: string; text: string }) {
  return <div className="card flex flex-col items-center justify-center gap-3 p-10 text-center" data-testid="state-empty"><div className="grid h-12 w-12 place-items-center rounded-2xl bg-secondary text-primary"><Leaf className="h-5 w-5" /></div><p className="font-bold">{title}</p><p className="max-w-sm text-sm text-muted-foreground">{text}</p></div>;
}

const navFor = (role: Role) => role === 'farmer'
  ? [{ href: '/dashboard', label: 'Overview', icon: Home }, { href: '/bookings', label: 'Bookings', icon: CalendarDays }, { href: '/centres', label: 'Centres', icon: MapPin }, { href: '/payments', label: 'Payments', icon: CreditCard }, { href: '/profile', label: 'My profile', icon: UserRound }]
  : role === 'officer'
    ? [{ href: '/officer', label: 'Daily operations', icon: ClipboardList }, { href: '/centres', label: 'Centre status', icon: MapPin }]
    : [{ href: '/admin', label: 'Administration', icon: BarChart3 }, { href: '/centres', label: 'Centre network', icon: MapPin }];

function Brand() {
  return <div className="flex items-center gap-3"><div className="brand-mark"><Sprout className="h-5 w-5" /></div><div><p className="text-sm font-bold tracking-tight">Smart Farmer</p><p className="font-mono-ui text-[9px] uppercase tracking-[.15em] opacity-60">Assistance network</p></div></div>;
}

function Shell({ children, role, onSignOut }: { children: ReactNode; role: Role; onSignOut: () => void }) {
  const [location] = useLocation();
  const nav = navFor(role);
  const [notificationsOpen, setNotificationsOpen] = useState(false);
  const notifications = useListNotifications({ query: { queryKey: getListNotificationsQueryKey() } });
  const markRead = useMarkNotificationRead();
  const unread = notifications.data?.filter(n => !n.read).length ?? 0;
  return <div className="app-shell flex">
    <aside className="side-rail hidden shrink-0 flex-col px-4 py-6 md:flex">
      <div className="mb-12 px-2"><Brand /></div>
      <p className="eyebrow mb-3 px-3 text-primary-foreground/50">Workspace</p>
      <nav className="space-y-1">{nav.map(item => { const Icon = item.icon; return <Link key={item.href} href={item.href} className={`nav-item ${location === item.href ? 'active' : ''}`} data-testid={`link-nav-${item.label.toLowerCase().replaceAll(' ', '-')}`}><Icon className="h-[17px] w-[17px]" /><span>{item.label}</span>{location === item.href && <ChevronRight className="ml-auto h-4 w-4" />}</Link>; })}</nav>
      <div className="mt-auto space-y-2"><div className="mb-5 rounded-2xl bg-primary-foreground/10 p-4"><p className="text-xs font-bold">Need a hand?</p><p className="mt-1 text-xs leading-5 text-primary-foreground/60">Your local procurement helpline is available during centre hours.</p><button className="mt-3 flex items-center gap-1 text-xs font-bold text-accent" data-testid="button-help"><Phone className="h-3 w-3" /> Contact support</button></div><button onClick={onSignOut} className="nav-item" data-testid="button-sign-out"><LogOut className="h-[17px] w-[17px]" /> Sign out</button></div>
    </aside>
    <div className="content-wrap">
      <header className="topbar flex items-center justify-between px-4 md:px-8">
        <div className="flex items-center gap-3 md:hidden"><button className="btn btn-quiet p-2" data-testid="button-mobile-menu"><Menu className="h-5 w-5" /></button><Brand /></div>
        <div className="hidden items-center gap-2 text-sm text-muted-foreground md:flex"><span className="font-mono-ui text-xs text-primary">/</span><span>{titleCase(location.split('/')[1] || 'dashboard')}</span></div>
        <div className="relative ml-auto flex items-center gap-2">
          <button className="relative grid h-10 w-10 place-items-center rounded-xl text-muted-foreground hover:bg-muted" onClick={() => setNotificationsOpen(!notificationsOpen)} data-testid="button-notifications"><Bell className="h-[18px] w-[18px]" />{unread > 0 && <span className="absolute right-2 top-2 h-2 w-2 rounded-full bg-accent" />}</button>
          {notificationsOpen && <div className="absolute right-0 top-12 z-40 w-[min(360px,calc(100vw-32px))] rounded-2xl border border-border bg-card p-2 shadow-xl" data-testid="panel-notifications"><div className="flex items-center justify-between px-3 py-2"><p className="font-bold">Notifications</p><span className="badge badge-amber">{unread} new</span></div>{notifications.isLoading ? <LoadingState rows={2} /> : notifications.data?.length ? notifications.data.slice(0, 4).map(n => <button key={n.id} className="w-full rounded-xl p-3 text-left hover:bg-muted" onClick={() => markRead.mutate({ notificationId: n.id }, { onSuccess: () => queryClient.invalidateQueries({ queryKey: getListNotificationsQueryKey() }) })} data-testid={`notification-${n.id}`}><p className="text-sm font-bold">{n.title}</p><p className="mt-1 text-xs text-muted-foreground">{n.message}</p><p className="mt-1 font-mono-ui text-[10px] text-muted-foreground">{n.time}</p></button>) : <p className="p-4 text-sm text-muted-foreground">You are all caught up.</p>}</div>}
          <div className="ml-1 hidden items-center gap-2 border-l border-border pl-4 sm:flex"><div className="grid h-9 w-9 place-items-center rounded-xl bg-secondary text-xs font-bold text-secondary-foreground">SF</div><div><p className="text-xs font-bold">{role === 'farmer' ? 'Farmer workspace' : `${titleCase(role)} workspace`}</p><p className="text-[11px] text-muted-foreground">Live operations</p></div></div>
        </div>
      </header>
      {children}
      <nav className="bottom-nav">{nav.slice(0, 4).map(item => { const Icon = item.icon; return <Link key={item.href} href={item.href} className={`bottom-item ${location === item.href ? 'active' : ''}`} data-testid={`mobile-nav-${item.label.toLowerCase().replaceAll(' ', '-')}`}><Icon className="h-[17px] w-[17px]" /><span>{item.label}</span></Link>; })}</nav>
    </div>
  </div>;
}

function Landing({ onLogin }: { onLogin: (role: Role) => void }) {
  const login = useDemoLogin();
  const [error, setError] = useState('');
  const roles: { role: Role; title: string; body: string; icon: typeof Tractor; accent: string }[] = [
    { role: 'farmer', title: 'Farmer', body: 'Book a slot, follow your crop, get paid.', icon: Tractor, accent: 'bg-secondary' },
    { role: 'officer', title: 'Procurement officer', body: 'Run your centre day with less guesswork.', icon: ClipboardList, accent: 'bg-accent/20' },
    { role: 'admin', title: 'Government admin', body: 'See the network clearly, act early.', icon: ShieldCheck, accent: 'bg-primary/10' },
  ];
  const choose = (role: Role) => { setError(''); login.mutate({ data: { role } }, { onSuccess: () => { sessionStorage.setItem('sf_role', role); onLogin(role); }, onError: () => setError('Demo sign-in is temporarily unavailable. Please try again.') }); };
  return <main className="login-pattern min-h-[100dvh] px-5 py-6 text-primary-foreground md:px-10 md:py-10">
    <div className="mx-auto flex max-w-7xl flex-col gap-14"><Brand /><div className="grid items-center gap-12 lg:grid-cols-[1.05fr_.95fr] lg:gap-24"><div className="max-w-2xl fade-up"><p className="eyebrow text-accent">One clear view of the harvest</p><h1 className="mt-5 text-balance text-5xl font-bold leading-[.98] tracking-[-.07em] md:text-7xl">From field gate<br /><span className="text-accent">to payment.</span></h1><p className="mt-7 max-w-lg text-lg leading-8 text-primary-foreground/70">Smart Farmer Assistance keeps intake, procurement and payment moving together — with fewer queues and more certainty.</p><div className="mt-10 flex flex-wrap gap-3 text-xs text-primary-foreground/60"><span className="flex items-center gap-2"><Check className="h-4 w-4 text-accent" /> Government-backed workflow</span><span className="flex items-center gap-2"><Check className="h-4 w-4 text-accent" /> Built for low bandwidth</span></div></div><div className="login-panel rounded-[26px] p-5 text-foreground shadow-2xl md:p-7 fade-up delay-2"><div className="mb-6"><p className="eyebrow text-primary">Choose a demo workspace</p><h2 className="mt-2 text-2xl font-bold tracking-tight">Start where you work</h2><p className="mt-1 text-sm text-muted-foreground">No password needed for this preview.</p></div><div className="space-y-3">{roles.map(({ role, title, body, icon: Icon, accent }) => <button key={role} onClick={() => choose(role)} disabled={login.isPending} className="group flex w-full items-center gap-4 rounded-2xl border border-border bg-card p-4 text-left transition hover:-translate-y-0.5 hover:border-primary/40 hover:shadow-lg disabled:opacity-60" data-testid={`button-login-${role}`}><div className={`grid h-11 w-11 shrink-0 place-items-center rounded-xl ${accent}`}><Icon className="h-5 w-5 text-primary" /></div><div className="min-w-0 flex-1"><p className="font-bold">{title}</p><p className="mt-0.5 text-xs text-muted-foreground">{body}</p></div><ArrowRight className="h-4 w-4 text-muted-foreground transition group-hover:translate-x-1 group-hover:text-primary" /></button>)}</div>{error && <p className="mt-4 flex items-center gap-2 text-sm text-destructive" data-testid="text-login-error"><CircleAlert className="h-4 w-4" />{error}</p>}<p className="mt-7 text-center text-[11px] text-muted-foreground">Demo data is isolated to this workspace.</p></div></div><div className="grid gap-4 border-t border-primary-foreground/15 pt-5 text-sm text-primary-foreground/60 md:grid-cols-3"><div><span className="font-mono-ui text-accent">01</span><p className="mt-2 font-bold text-primary-foreground">Know your slot</p><p className="mt-1">Capacity and arrival windows before you leave home.</p></div><div><span className="font-mono-ui text-accent">02</span><p className="mt-2 font-bold text-primary-foreground">Know your quality</p><p className="mt-1">Every check recorded, with no paper trail to chase.</p></div><div><span className="font-mono-ui text-accent">03</span><p className="mt-2 font-bold text-primary-foreground">Know your payment</p><p className="mt-1">A simple timeline from procurement to rupees in account.</p></div></div></div>
  </main>;
}

function PageHeader({ eyebrow, title, description, action }: { eyebrow: string; title: string; description?: string; action?: ReactNode }) {
  return <div className="mb-8 flex flex-col justify-between gap-5 md:flex-row md:items-end"><div><p className="eyebrow">{eyebrow}</p><h1 className="page-title mt-2">{title}</h1>{description && <p className="mt-2 max-w-2xl text-sm leading-6 text-muted-foreground">{description}</p>}</div>{action}</div>;
}

function DashboardPage() {
  const query = useGetDashboard({ query: { queryKey: getGetDashboardQueryKey() } });
  if (query.isLoading) return <main className="main-content"><LoadingState rows={6} /></main>;
  if (query.isError || !query.data) return <main className="main-content"><ErrorState onRetry={() => query.refetch()} /></main>;
  const { stats, upcomingBooking, centres, notifications } = query.data;
  return <main className="main-content fade-up"><PageHeader eyebrow="Farmer overview" title={`Good morning, ${query.data.user.name.split(' ')[0]}.`} description="Here is what is moving today across your farm and nearest centre." action={<Link href="/bookings/new" className="btn btn-accent" data-testid="link-book-new"><CalendarDays className="h-4 w-4" /> Book a procurement slot</Link>} />
    <div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4">{[{ label: 'Land under cultivation', value: `${stats.totalLand} acres`, sub: 'Registered this season', icon: Droplets }, { label: 'Current crop', value: stats.currentCrop, sub: `${stats.expectedQuantity} expected`, icon: Leaf }, { label: 'Booked slots', value: stats.bookedSlots, sub: 'This procurement season', icon: CalendarDays }, { label: 'Pending payments', value: stats.pendingPayments, sub: `${stats.completedProcurements} procurements completed`, icon: IndianRupee }].map(({ label, value, sub, icon: Icon }, i) => <div key={label} className={`card stat-card card-hover p-5 fade-up delay-${Math.min(i + 1, 3)}`} data-testid={`stat-${label.toLowerCase().replaceAll(' ', '-')}`}><div className="flex items-center justify-between"><p className="text-xs font-bold text-muted-foreground">{label}</p><Icon className="h-4 w-4 text-primary" /></div><p className="mt-5 text-2xl font-bold tracking-tight">{value}</p><p className="mt-1 text-xs text-muted-foreground">{sub}</p></div>)}</div>
    <div className="mt-5 grid gap-5 lg:grid-cols-[1.3fr_.7fr]"><div className="card overflow-hidden"><div className="flex items-center justify-between border-b border-border p-5"><div><p className="eyebrow">Next on the calendar</p><h2 className="mt-1 text-lg font-bold">Your upcoming procurement</h2></div><Link href="/bookings" className="text-xs font-bold text-primary" data-testid="link-all-bookings">View all <ArrowRight className="ml-1 inline h-3 w-3" /></Link></div>{upcomingBooking ? <div className="p-5"><div className="flex flex-col justify-between gap-5 sm:flex-row"><div><div className="flex items-center gap-2"><span className="badge badge-green"><span className="h-1.5 w-1.5 rounded-full bg-primary" /> {titleCase(upcomingBooking.status)}</span><span className="font-mono-ui text-[10px] text-muted-foreground">{upcomingBooking.id}</span></div><h3 className="mt-4 text-2xl font-bold">{upcomingBooking.crop} <span className="text-muted-foreground">/ {upcomingBooking.quantity} qtl</span></h3><p className="mt-2 flex items-center gap-2 text-sm text-muted-foreground"><MapPin className="h-4 w-4 text-accent" /> {upcomingBooking.centre.name}</p><p className="mt-1 flex items-center gap-2 text-sm text-muted-foreground"><CalendarDays className="h-4 w-4 text-accent" /> {formatDate(upcomingBooking.date)} · {upcomingBooking.time}</p></div><div className="min-w-[180px] rounded-2xl bg-secondary/60 p-4"><p className="eyebrow">Arrival note</p><p className="mt-2 text-sm font-bold leading-5">{upcomingBooking.arrival}</p><div className="mt-4 flex items-center gap-2 text-xs text-muted-foreground"><Clock3 className="h-3.5 w-3.5" /> Capacity is live</div></div></div><div className="mt-6 flex flex-wrap gap-2"><span className="badge badge-green"><Check className="h-3 w-3" /> Slot confirmed</span><span className="badge badge-slate">Quality check at centre</span><span className="badge badge-slate">Payment after acceptance</span></div></div> : <EmptyState title="No upcoming procurement" text="Choose a centre and reserve a time that works for your harvest." />}</div>
      <div className="card p-5"><div className="flex items-center justify-between"><div><p className="eyebrow">Nearby now</p><h2 className="mt-1 text-lg font-bold">Centre capacity</h2></div><Link href="/centres" className="text-xs font-bold text-primary" data-testid="link-centres">Explore <ArrowRight className="ml-1 inline h-3 w-3" /></Link></div><div className="mt-5 space-y-4">{centres.slice(0, 3).map(c => <CentreMini key={c.id} centre={c} />)}</div></div></div>
    <div className="mt-5 grid gap-5 lg:grid-cols-[.8fr_1.2fr]"><div className="card p-5"><div className="flex items-center justify-between"><div><p className="eyebrow">Updates</p><h2 className="mt-1 text-lg font-bold">What needs your attention</h2></div><Bell className="h-4 w-4 text-accent" /></div><div className="mt-4 space-y-1">{notifications.slice(0, 4).map(n => <div key={n.id} className="flex gap-3 rounded-xl p-3 hover:bg-muted" data-testid={`notification-row-${n.id}`}><div className={`mt-1 h-2 w-2 shrink-0 rounded-full ${n.read ? 'bg-muted-foreground/30' : 'bg-accent'}`} /><div><p className="text-sm font-bold">{n.title}</p><p className="mt-0.5 text-xs leading-5 text-muted-foreground">{n.message}</p><p className="mt-1 font-mono-ui text-[10px] text-muted-foreground">{n.time}</p></div></div>)}</div></div><div className="rounded-[18px] bg-primary p-6 text-primary-foreground"><div className="flex items-start justify-between"><div><p className="eyebrow text-accent">Your crop journey</p><h2 className="mt-2 max-w-sm text-2xl font-bold tracking-tight">Good records make good payments.</h2><p className="mt-3 max-w-md text-sm leading-6 text-primary-foreground/65">Keep your profile and crop details current so the centre can plan for your arrival.</p></div><TrendingUp className="h-7 w-7 text-accent" /></div><Link href="/profile" className="btn btn-accent mt-6" data-testid="link-complete-profile">Review my profile <ArrowRight className="h-4 w-4" /></Link></div></div>
  </main>;
}

function CentreMini({ centre }: { centre: ProcurementCentre }) {
  const fullness = Math.min(100, Math.round(((centre.capacity - centre.remaining) / centre.capacity) * 100));
  return <div className="flex items-center gap-3"><div className="grid h-9 w-9 shrink-0 place-items-center rounded-xl bg-secondary text-primary"><LocateFixed className="h-4 w-4" /></div><div className="min-w-0 flex-1"><div className="flex items-center justify-between gap-2"><p className="truncate text-sm font-bold">{centre.name}</p><span className={`text-[10px] font-bold ${centre.open ? 'text-primary' : 'text-destructive'}`}>{centre.open ? 'Open' : 'Closed'}</span></div><div className="mt-2 progress-track"><div className="progress-fill" style={{ width: `${fullness}%` }} /></div><p className="mt-1 text-[10px] text-muted-foreground">{centre.remaining} qtl remaining · {centre.distance}</p></div></div>;
}

function BookingsPage() {
  const [search, setSearch] = useState('');
  const [status, setStatus] = useState<'all' | 'upcoming' | 'completed' | 'cancelled' | 'pending'>('all');
  const [selected, setSelected] = useState<string | null>(null);
  const query = useListBookings({ search: search || undefined, status }, { query: { queryKey: getListBookingsQueryKey({ search: search || undefined, status }) } });
  const detail = useGetBooking(selected ?? '', { query: { enabled: !!selected, queryKey: getGetBookingQueryKey(selected ?? '') } });
  const cancel = useCancelBooking();
  const update = useUpdateBooking();
  const refresh = () => queryClient.invalidateQueries({ queryKey: getListBookingsQueryKey({ search: search || undefined, status }) });
  return <main className="main-content fade-up"><PageHeader eyebrow="Your harvest plan" title="Bookings" description="Keep every arrival window in one place." action={<Link href="/bookings/new" className="btn btn-accent" data-testid="link-new-booking"><CalendarDays className="h-4 w-4" /> New booking</Link>} />
    <div className="card mb-5 flex flex-col gap-3 p-3 sm:flex-row"><div className="relative flex-1"><Search className="absolute left-3 top-3 h-4 w-4 text-muted-foreground" /><input className="field pl-10" value={search} onChange={e => setSearch(e.target.value)} placeholder="Search by crop or centre" data-testid="input-booking-search" /></div><select className="field sm:w-44" value={status} onChange={e => setStatus(e.target.value as typeof status)} data-testid="select-booking-status"><option value="all">All bookings</option><option value="upcoming">Upcoming</option><option value="pending">Pending</option><option value="completed">Completed</option><option value="cancelled">Cancelled</option></select></div>
    {query.isLoading ? <LoadingState rows={5} /> : query.isError ? <ErrorState onRetry={() => query.refetch()} /> : !query.data?.length ? <EmptyState title="No bookings found" text="Your reserved procurement slots will appear here." /> : <div className="grid gap-3">{query.data.map(b => <button key={b.id} onClick={() => setSelected(b.id)} className="card card-hover flex w-full flex-col gap-4 p-5 text-left sm:flex-row sm:items-center" data-testid={`booking-card-${b.id}`}><div className="grid h-11 w-11 shrink-0 place-items-center rounded-xl bg-secondary text-primary"><Leaf className="h-5 w-5" /></div><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><h3 className="font-bold">{b.crop} · {b.quantity} qtl</h3><StatusBadge status={b.status} /></div><p className="mt-1 text-sm text-muted-foreground">{b.centre.name} · {formatDate(b.date)} · {b.time}</p></div><div className="flex items-center gap-4 sm:text-right"><div><p className="font-mono-ui text-[10px] text-muted-foreground">{b.id}</p><p className="mt-1 text-xs font-bold text-primary">{titleCase(b.procurement)}</p></div><ChevronRight className="h-4 w-4 text-muted-foreground" /></div></button>)}</div>}
    {selected && <div className="fixed inset-0 z-50 flex items-end justify-center bg-foreground/30 p-0 sm:items-center sm:p-5" onClick={() => setSelected(null)}><div className="max-h-[90vh] w-full max-w-xl overflow-auto rounded-t-3xl bg-card p-6 shadow-2xl sm:rounded-3xl" onClick={e => e.stopPropagation()} data-testid="panel-booking-detail">{detail.isLoading ? <LoadingState rows={4} /> : detail.data ? <><div className="flex items-start justify-between"><div><p className="eyebrow">Booking detail</p><h2 className="mt-1 text-2xl font-bold">{detail.data.crop} · {detail.data.quantity} qtl</h2><p className="mt-1 font-mono-ui text-[10px] text-muted-foreground">{detail.data.id}</p></div><button className="btn btn-quiet p-2" onClick={() => setSelected(null)} data-testid="button-close-detail"><X className="h-4 w-4" /></button></div><div className="mt-6 grid gap-3 sm:grid-cols-2">{[['Centre', detail.data.centre.name], ['Arrival', `${formatDate(detail.data.date)} · ${detail.data.time}`], ['Quality', detail.data.quality], ['Procurement', detail.data.procurement], ['Payment', detail.data.payment], ['Arrival note', detail.data.arrival]].map(([label, value]) => <div key={label} className="rounded-xl bg-muted p-3"><p className="eyebrow">{label}</p><p className="mt-1 text-sm font-bold">{value}</p></div>)}</div><div className="mt-6 flex flex-wrap gap-2">{detail.data.status !== 'cancelled' && detail.data.status !== 'completed' && <><button className="btn btn-outline" onClick={() => update.mutate({ bookingId: detail.data!.id, data: { status: 'approaching' } }, { onSuccess: refresh })} data-testid="button-mark-arriving"><Activity className="h-4 w-4" /> Mark arriving</button><button className="btn btn-danger" onClick={() => cancel.mutate({ bookingId: detail.data!.id }, { onSuccess: () => { refresh(); setSelected(null); } })} data-testid="button-cancel-booking"><X className="h-4 w-4" /> Cancel booking</button></>}</div></> : <ErrorState />}</div></div>}
  </main>;
}

function StatusBadge({ status }: { status: string }) {
  const cls = status === 'confirmed' || status === 'completed' ? 'badge-green' : status === 'cancelled' ? 'badge-red' : status === 'approaching' ? 'badge-amber' : 'badge-slate';
  return <span className={`badge ${cls}`}>{titleCase(status)}</span>;
}

function NewBookingPage() {
  const [, setLocation] = useLocation();
  const [step, setStep] = useState(1);
  const [crop, setCrop] = useState('');
  const [quantity, setQuantity] = useState('');
  const [centreId, setCentreId] = useState('');
  const [slotId, setSlotId] = useState('');
  const centres = useListCentres({ query: { queryKey: getListCentresQueryKey() } });
  const slots = useListCentreSlots(centreId, { query: { enabled: !!centreId, queryKey: getListCentreSlotsQueryKey(centreId) } });
  const create = useCreateBooking();
  const [error, setError] = useState('');
  const selectedCentre = centres.data?.find(c => c.id === centreId);
  const canNext = step === 1 ? !!crop && Number(quantity) > 0 : !!centreId && !!slotId;
  const submit = () => { setError(''); create.mutate({ data: { crop, quantity: Number(quantity), centreId, slotId } }, { onSuccess: () => { queryClient.invalidateQueries({ queryKey: getListBookingsQueryKey() }); queryClient.invalidateQueries({ queryKey: getGetDashboardQueryKey() }); setLocation('/bookings'); }, onError: () => setError('This slot could not be reserved. Please select another time.') }); };
  return <main className="main-content fade-up"><PageHeader eyebrow="Reserve your window" title="Book a procurement slot" description="Two steps, a clear arrival time, and no queue-side surprises." action={<Link href="/bookings" className="btn btn-outline" data-testid="link-back-bookings">Back to bookings</Link>} /><div className="mx-auto max-w-3xl"><div className="mb-7 flex items-center gap-2">{[1, 2, 3].map(n => <div key={n} className="flex flex-1 items-center gap-2"><div className={`grid h-8 w-8 shrink-0 place-items-center rounded-full text-xs font-bold ${step >= n ? 'bg-primary text-primary-foreground' : 'bg-muted text-muted-foreground'}`}>{step > n ? <Check className="h-4 w-4" /> : n}</div><div className={`h-1 flex-1 rounded-full ${step > n ? 'bg-primary' : 'bg-muted'}`} /></div>)}</div><div className="card p-5 md:p-8">{step === 1 && <><p className="eyebrow">Step 01 · Crop intake</p><h2 className="mt-2 text-2xl font-bold">Tell us what is coming in</h2><p className="mt-1 text-sm text-muted-foreground">This helps the centre plan its receiving bay.</p><div className="mt-7 grid gap-5 sm:grid-cols-2"><label className="block"><span className="mb-2 block text-sm font-bold">Crop</span><select className="field" value={crop} onChange={e => setCrop(e.target.value)} data-testid="select-booking-crop"><option value="">Select crop</option><option>Wheat</option><option>Rice</option><option>Mustard</option><option>Maize</option><option>Cotton</option></select></label><label className="block"><span className="mb-2 block text-sm font-bold">Expected quantity (quintals)</span><input className="field" type="number" min="1" value={quantity} onChange={e => setQuantity(e.target.value)} placeholder="e.g. 24" data-testid="input-booking-quantity" /></label></div></>}
    {step === 2 && <><p className="eyebrow">Step 02 · Pick a centre</p><h2 className="mt-2 text-2xl font-bold">Where would you like to go?</h2><p className="mt-1 text-sm text-muted-foreground">Showing centres near your registered village.</p><div className="mt-6 grid gap-3">{centres.isLoading ? <LoadingState rows={3} /> : centres.data?.map(c => <button key={c.id} onClick={() => { setCentreId(c.id); setSlotId(''); }} className={`flex items-center gap-4 rounded-2xl border p-4 text-left transition ${centreId === c.id ? 'border-primary bg-primary/5' : 'border-border hover:border-primary/30'}`} data-testid={`button-centre-${c.id}`}><div className="grid h-10 w-10 shrink-0 place-items-center rounded-xl bg-secondary text-primary"><MapPin className="h-4 w-4" /></div><div className="min-w-0 flex-1"><p className="font-bold">{c.name}</p><p className="mt-1 truncate text-xs text-muted-foreground">{c.address} · {c.distance}</p></div><div className="text-right"><p className={`text-xs font-bold ${c.open ? 'text-primary' : 'text-destructive'}`}>{c.open ? 'Open' : 'Closed'}</p><p className="mt-1 text-[10px] text-muted-foreground">{c.remaining} qtl left</p></div>{centreId === c.id && <Check className="h-4 w-4 text-primary" />}</button>)}</div></>}
    {step === 3 && <><p className="eyebrow">Step 03 · Arrival time</p><h2 className="mt-2 text-2xl font-bold">Choose a slot that fits</h2><p className="mt-1 text-sm text-muted-foreground">{selectedCentre?.name} · {quantity} qtl of {crop}</p><div className="mt-6 grid gap-3 sm:grid-cols-2">{slots.isLoading ? <LoadingState rows={4} /> : slots.data?.map(s => <SlotCard key={s.id} slot={s} selected={slotId === s.id} onClick={() => setSlotId(s.id)} />)}</div></>}
    {error && <p className="mt-5 flex items-center gap-2 text-sm text-destructive" data-testid="text-booking-error"><CircleAlert className="h-4 w-4" />{error}</p>}<div className="mt-8 flex justify-between gap-3 border-t border-border pt-5">{step > 1 ? <button className="btn btn-quiet" onClick={() => setStep(step - 1)} data-testid="button-booking-previous">Previous</button> : <span />}{step < 3 ? <button className="btn btn-primary" disabled={!canNext} onClick={() => setStep(step + 1)} data-testid="button-booking-next">Continue <ArrowRight className="h-4 w-4" /></button> : <button className="btn btn-accent" disabled={!canNext || create.isPending} onClick={submit} data-testid="button-confirm-booking">{create.isPending ? 'Reserving…' : 'Confirm this slot'} <Check className="h-4 w-4" /></button>}</div></div></div></main>;
}
function SlotCard({ slot, selected, onClick }: { slot: Slot; selected: boolean; onClick: () => void }) { return <button onClick={onClick} disabled={!slot.available} className={`relative rounded-2xl border p-4 text-left ${selected ? 'border-primary bg-primary/5' : 'border-border hover:border-primary/30'} disabled:cursor-not-allowed disabled:opacity-45`} data-testid={`button-slot-${slot.id}`}><div className="flex items-center justify-between"><p className="font-bold">{slot.label}</p>{slot.recommended && <span className="badge badge-amber">Recommended</span>}</div><p className="mt-2 text-sm text-muted-foreground">{formatDate(slot.date)}</p><div className="mt-4 flex items-center justify-between text-xs"><span className="font-bold text-primary">{slot.available} spots left</span><span className="text-muted-foreground">of {slot.capacity}</span></div>{selected && <Check className="absolute right-4 bottom-4 h-4 w-4 text-primary" />}</button>; }

function CentresPage() {
  const query = useListCentres({ query: { queryKey: getListCentresQueryKey() } });
  const [selected, setSelected] = useState<ProcurementCentre | null>(null);
  return <main className="main-content fade-up"><PageHeader eyebrow="The local network" title="Procurement centres" description="Live capacity, queue length and travel distance for centres around you." action={<button className="btn btn-outline" onClick={() => query.refetch()} data-testid="button-refresh-centres"><RefreshCw className="h-4 w-4" /> Refresh status</button>} />{query.isLoading ? <LoadingState rows={5} /> : query.isError ? <ErrorState onRetry={() => query.refetch()} /> : !query.data?.length ? <EmptyState title="No centres nearby" text="Centre availability will appear here once the network is online." /> : <div className="grid gap-4 lg:grid-cols-2">{query.data.map(c => <button key={c.id} onClick={() => setSelected(c)} className="card card-hover flex w-full gap-4 p-5 text-left" data-testid={`centre-card-${c.id}`}><div className="grid h-11 w-11 shrink-0 place-items-center rounded-xl bg-secondary text-primary"><MapPin className="h-5 w-5" /></div><div className="min-w-0 flex-1"><div className="flex items-start justify-between gap-3"><div><h2 className="font-bold">{c.name}</h2><p className="mt-1 text-xs text-muted-foreground">{c.address}, {c.district}</p></div><span className={`badge ${c.open ? 'badge-green' : 'badge-red'}`}>{c.open ? 'Open now' : 'Closed'}</span></div><div className="mt-5 grid grid-cols-3 gap-2 border-t border-border pt-4"><div><p className="eyebrow">Distance</p><p className="mt-1 text-sm font-bold">{c.distance}</p></div><div><p className="eyebrow">Queue</p><p className="mt-1 text-sm font-bold">{c.queue} vehicles</p></div><div><p className="eyebrow">Wait</p><p className="mt-1 text-sm font-bold">{c.waitMinutes} min</p></div></div><div className="mt-4"><div className="flex justify-between text-[10px] text-muted-foreground"><span>{c.remaining} qtl capacity remaining</span><span>{c.capacity} qtl total</span></div><div className="mt-1 progress-track"><div className="progress-fill" style={{ width: `${Math.min(100, ((c.capacity - c.remaining) / c.capacity) * 100)}%` }} /></div></div></div><ChevronRight className="mt-1 h-4 w-4 shrink-0 text-muted-foreground" /></button>)}</div>}{selected && <CentrePanel centre={selected} onClose={() => setSelected(null)} />}</main>;
}
function CentrePanel({ centre, onClose }: { centre: ProcurementCentre; onClose: () => void }) { const slots = useListCentreSlots(centre.id, { query: { queryKey: getListCentreSlotsQueryKey(centre.id) } }); return <div className="fixed inset-0 z-50 flex items-end justify-center bg-foreground/30 p-0 sm:items-center sm:p-5" onClick={onClose}><div className="w-full max-w-lg rounded-t-3xl bg-card p-6 shadow-2xl sm:rounded-3xl" onClick={e => e.stopPropagation()} data-testid="panel-centre-detail"><div className="flex items-start justify-between"><div><p className="eyebrow">Centre detail</p><h2 className="mt-1 text-2xl font-bold">{centre.name}</h2><p className="mt-1 text-sm text-muted-foreground">{centre.address}</p></div><button className="btn btn-quiet p-2" onClick={onClose} data-testid="button-close-centre"><X className="h-4 w-4" /></button></div><div className="mt-6 grid grid-cols-2 gap-3"><div className="rounded-xl bg-muted p-3"><p className="eyebrow">Current queue</p><p className="mt-1 text-lg font-bold">{centre.queue} vehicles</p></div><div className="rounded-xl bg-muted p-3"><p className="eyebrow">Estimated wait</p><p className="mt-1 text-lg font-bold">{centre.waitMinutes} min</p></div></div><p className="eyebrow mt-6">Available slots</p><div className="mt-3 space-y-2">{slots.isLoading ? <LoadingState rows={3} /> : slots.data?.slice(0, 4).map(s => <div key={s.id} className="flex items-center justify-between rounded-xl border border-border p-3"><div><p className="text-sm font-bold">{s.label}</p><p className="text-xs text-muted-foreground">{formatDate(s.date)}</p></div><span className="text-xs font-bold text-primary">{s.available} spots</span></div>)}</div><Link href="/bookings/new" className="btn btn-primary mt-6 w-full" data-testid="link-centre-book">Book at this centre <ArrowRight className="h-4 w-4" /></Link></div></div>; }

function PaymentsPage() {
  const query = useListPayments({ query: { queryKey: getListPaymentsQueryKey() } });
  return <main className="main-content fade-up"><PageHeader eyebrow="Money trail" title="Payments" description="A transparent record from accepted crop to money in your account." />{query.isLoading ? <LoadingState rows={5} /> : query.isError ? <ErrorState onRetry={() => query.refetch()} /> : !query.data?.length ? <EmptyState title="No payments yet" text="Once a procurement is completed, its payment record will appear here." /> : <div className="grid gap-5 lg:grid-cols-[1.1fr_.9fr]"><div className="card overflow-hidden"><div className="border-b border-border p-5"><p className="eyebrow">Payment records</p><h2 className="mt-1 text-lg font-bold">Recent transactions</h2></div><div className="divide-y divide-border">{query.data.map(p => <div key={p.id} className="flex flex-col gap-3 p-5 sm:flex-row sm:items-center" data-testid={`payment-row-${p.id}`}><div className="grid h-10 w-10 shrink-0 place-items-center rounded-xl bg-secondary text-primary"><IndianRupee className="h-4 w-4" /></div><div className="flex-1"><div className="flex flex-wrap items-center gap-2"><p className="font-bold">{p.crop} · {p.quantity} qtl</p><StatusBadge status={p.status} /></div><p className="mt-1 text-xs text-muted-foreground">{formatDate(p.date)} · {p.transactionId}</p></div><div className="sm:text-right"><p className="text-lg font-bold">{money(p.amount)}</p><p className="text-xs text-muted-foreground">Gross {money(p.gross)} · −{money(p.deductions)}</p></div></div>)}</div></div><div className="card p-5"><p className="eyebrow">How payment moves</p><h2 className="mt-1 text-lg font-bold">One clear trail</h2><div className="relative mt-6 space-y-6 pl-7">{['Quality accepted', 'Procurement recorded', 'Payment initiated', 'Amount credited'].map((label, i) => <div key={label} className="relative"><div className="absolute -left-7 top-0 grid h-[19px] w-[19px] place-items-center rounded-full bg-primary text-primary-foreground"><Check className="h-3 w-3" /></div>{i < 3 && <div className="timeline-line" />}<p className="text-sm font-bold">{label}</p><p className="mt-1 text-xs text-muted-foreground">{i === 0 ? 'Quality details are visible at the centre.' : i === 3 ? 'Your bank account receives the final amount.' : 'You can follow this update from your records.'}</p></div>)}</div><div className="mt-7 rounded-xl bg-secondary/60 p-4"><p className="text-xs font-bold">Account ending {query.data[0]?.transactionId?.slice(-4) ?? '••••'}</p><p className="mt-1 text-xs text-muted-foreground">Payment details are protected in this view.</p></div></div></div>}</main>;
}

function ProfilePage() {
  const query = useGetProfile({ query: { queryKey: getGetProfileQueryKey() } });
  const update = useUpdateProfile();
  const [form, setForm] = useState<Record<string, string>>({});
  const [saved, setSaved] = useState(false);
  if (query.isLoading) return <main className="main-content"><LoadingState rows={6} /></main>;
  if (query.isError || !query.data) return <main className="main-content"><ErrorState onRetry={() => query.refetch()} /></main>;
  const profile = query.data; const values = { name: form.name ?? profile.name, village: form.village ?? profile.village, district: form.district ?? profile.district, state: form.state ?? profile.state, landArea: form.landArea ?? String(profile.landArea), expectedYield: form.expectedYield ?? profile.expectedYield };
  const set = (key: string, value: string) => { setSaved(false); setForm(f => ({ ...f, [key]: value })); };
  const save = () => update.mutate({ data: { name: values.name, village: values.village, district: values.district, state: values.state, landArea: Number(values.landArea), expectedYield: values.expectedYield, crops: profile.crops } }, { onSuccess: () => { setSaved(true); queryClient.invalidateQueries({ queryKey: getGetProfileQueryKey() }); } });
  return <main className="main-content fade-up"><PageHeader eyebrow="Your farmer record" title="My profile" description="Keep these details current so procurement teams can plan around your crop." action={saved ? <span className="badge badge-green"><Check className="h-3 w-3" /> Saved just now</span> : <button className="btn btn-primary" onClick={save} disabled={update.isPending} data-testid="button-save-profile">{update.isPending ? 'Saving…' : 'Save changes'}</button>} /><div className="grid gap-5 lg:grid-cols-[.65fr_1.35fr]"><div className="card p-6"><div className="flex items-center gap-4"><div className="grid h-16 w-16 place-items-center rounded-2xl bg-primary text-lg font-bold text-primary-foreground">{profile.name.split(' ').map(p => p[0]).join('').slice(0, 2)}</div><div><h2 className="text-xl font-bold">{profile.name}</h2><p className="mt-1 text-sm text-muted-foreground">{profile.mobile}</p></div></div><div className="mt-8"><div className="flex items-end justify-between"><div><p className="eyebrow">Profile completion</p><p className="mt-1 text-3xl font-bold">{profile.completion}%</p></div><span className="text-xs text-muted-foreground">Almost there</span></div><div className="mt-3 progress-track"><div className="progress-fill" style={{ width: `${profile.completion}%` }} /></div><p className="mt-3 text-xs leading-5 text-muted-foreground">A complete profile helps match capacity to your expected arrival.</p></div><div className="mt-8 rounded-2xl bg-secondary/60 p-4"><p className="eyebrow">Crops on record</p><div className="mt-3 flex flex-wrap gap-2">{profile.crops.map(c => <span className="badge badge-green" key={c}>{c}</span>)}</div></div></div><div className="card p-6"><p className="eyebrow">Farm details</p><h2 className="mt-1 text-lg font-bold">Your details</h2><div className="mt-6 grid gap-5 sm:grid-cols-2">{[['name', 'Full name'], ['village', 'Village'], ['district', 'District'], ['state', 'State'], ['landArea', 'Land area (acres)'], ['expectedYield', 'Expected yield']].map(([key, label]) => <label className="block" key={key}><span className="mb-2 block text-sm font-bold">{label}</span><input className="field" value={values[key as keyof typeof values]} onChange={e => set(key, e.target.value)} data-testid={`input-profile-${key}`} /></label>)}</div><div className="mt-6 rounded-xl border border-border p-4"><p className="eyebrow">Linked payment account</p><p className="mt-2 text-sm font-bold">{profile.maskedAccount}</p><p className="mt-1 text-xs text-muted-foreground">For account changes, contact your district office.</p></div></div></div></main>;
}

function OfficerPage() {
  const query = useGetOfficerDashboard({ query: { queryKey: getGetOfficerDashboardQueryKey() } });
  const update = useUpdateBooking();
  if (query.isLoading) return <main className="main-content"><LoadingState rows={6} /></main>;
  if (query.isError || !query.data) return <main className="main-content"><ErrorState onRetry={() => query.refetch()} /></main>;
  const d = query.data; const mutate = (id: string, status: 'confirmed' | 'approaching' | 'completed') => update.mutate({ bookingId: id, data: { status } }, { onSuccess: () => queryClient.invalidateQueries({ queryKey: getGetOfficerDashboardQueryKey() }) });
  const metrics: { label: string; value: number; Icon: typeof CalendarDays }[] = [['Today’s bookings', d.todayBookings, CalendarDays], ['Current queue', d.currentQueue, Users], ['Expected arrivals', d.expectedArrivals, Clock3], ['Completed', d.completed, Check]].map(([label, value, Icon]) => ({ label: label as string, value: value as number, Icon: Icon as typeof CalendarDays }));
  return <main className="main-content fade-up"><PageHeader eyebrow="Centre operations" title="Good morning, officer." description={`${d.centre.name} · ${d.centre.address}`} action={<span className="badge badge-green"><span className="h-1.5 w-1.5 rounded-full bg-primary" /> Centre live</span>} /><div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4">{metrics.map(({ label, value, Icon }) => <div key={label} className="card stat-card p-5"><Icon className="h-4 w-4 text-primary" /><p className="mt-5 text-2xl font-bold">{value}</p><p className="mt-1 text-xs font-bold text-muted-foreground">{label}</p></div>)}</div><div className="mt-5 grid gap-5 lg:grid-cols-[1.4fr_.6fr]"><div className="card overflow-hidden"><div className="flex items-center justify-between border-b border-border p-5"><div><p className="eyebrow">Live queue</p><h2 className="mt-1 text-lg font-bold">Today’s arrivals</h2></div><span className="font-mono-ui text-xs text-muted-foreground">{d.queue.length} records</span></div>{d.queue.length ? <div className="divide-y divide-border">{d.queue.map(b => <div className="flex flex-col gap-3 p-5 sm:flex-row sm:items-center" key={b.id} data-testid={`officer-row-${b.id}`}><div className="flex-1"><div className="flex flex-wrap items-center gap-2"><p className="font-bold">{b.crop} · {b.quantity} qtl</p><StatusBadge status={b.status} /></div><p className="mt-1 text-xs text-muted-foreground">{b.id} · {b.time} · {b.centre.name}</p></div><div className="flex gap-2">{b.status === 'pending' && <button className="btn btn-outline text-xs" onClick={() => mutate(b.id, 'confirmed')} data-testid={`button-confirm-${b.id}`}>Confirm arrival</button>}{b.status === 'confirmed' && <button className="btn btn-accent text-xs" onClick={() => mutate(b.id, 'approaching')} data-testid={`button-approach-${b.id}`}>Call next</button>}{b.status === 'approaching' && <button className="btn btn-primary text-xs" onClick={() => mutate(b.id, 'completed')} data-testid={`button-complete-${b.id}`}>Complete</button>}</div></div>)}</div> : <EmptyState title="Queue is clear" text="New confirmed arrivals will appear here." />}</div><div className="space-y-5"><div className="card p-5"><p className="eyebrow">Needs attention</p><div className="mt-5 space-y-4">{[['Quality checks', d.pendingQuality, 'Awaiting review'], ['Payments', d.pendingPayments, 'Ready to release']].map(([label, value, sub]) => <div className="flex items-center justify-between" key={String(label)}><div><p className="text-sm font-bold">{label as string}</p><p className="mt-1 text-xs text-muted-foreground">{sub as string}</p></div><span className="text-2xl font-bold text-primary">{value as number}</span></div>)}</div></div><div className="rounded-[18px] bg-secondary p-5"><p className="eyebrow">Capacity signal</p><p className="mt-2 text-2xl font-bold">{d.centre.remaining} qtl</p><p className="mt-1 text-xs leading-5 text-muted-foreground">Receiving capacity remaining today at this centre.</p><div className="mt-4 progress-track"><div className="progress-fill" style={{ width: `${((d.centre.capacity - d.centre.remaining) / d.centre.capacity) * 100}%` }} /></div></div></div></div></main>;
}

function AdminPage() {
  const query = useGetAdminDashboard({ query: { queryKey: getGetAdminDashboardQueryKey() } });
  if (query.isLoading) return <main className="main-content"><LoadingState rows={7} /></main>;
  if (query.isError || !query.data) return <main className="main-content"><ErrorState onRetry={() => query.refetch()} /></main>;
  const d = query.data; const maxTrend = Math.max(...d.bookingTrend.map(x => x.bookings), 1); const totalCrop = d.cropMix.reduce((sum, x) => sum + x.quantity, 0);
  const metrics: { label: string; value: string | number; Icon: typeof Users }[] = [['Farmers enrolled', d.totalFarmers, Users], ['Live centres', d.totalCentres, MapPin], ['Bookings today', d.todayBookings, CalendarDays], ['Pending payments', money(d.pendingPayments), IndianRupee]].map(([label, value, Icon]) => ({ label: label as string, value: value as string | number, Icon: Icon as typeof Users }));
  return <main className="main-content fade-up"><PageHeader eyebrow="Network administration" title="A clear view of the system." description="Monitor participation, intake and payment readiness across the procurement network." action={<button className="btn btn-outline" onClick={() => query.refetch()} data-testid="button-refresh-admin"><RefreshCw className="h-4 w-4" /> Refresh data</button>} /><div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4">{metrics.map(({ label, value, Icon }) => <div className="card stat-card p-5" key={label}><Icon className="h-4 w-4 text-primary" /><p className="mt-5 text-2xl font-bold">{value}</p><p className="mt-1 text-xs font-bold text-muted-foreground">{label}</p></div>)}</div><div className="mt-5 grid gap-5 lg:grid-cols-[1.25fr_.75fr]"><div className="card p-5"><div className="flex items-center justify-between"><div><p className="eyebrow">Booking rhythm</p><h2 className="mt-1 text-lg font-bold">Last seven days</h2></div><span className="badge badge-green"><Activity className="h-3 w-3" /> Live</span></div><div className="mt-7 flex h-52 items-end gap-2 border-b border-l border-border px-2 pb-0 pt-4">{d.bookingTrend.map((x, i) => <div className="flex h-full flex-1 flex-col items-center justify-end gap-2" key={x.day}><div className="w-full max-w-10 rounded-t-lg bg-primary transition hover:bg-accent" style={{ height: `${Math.max(8, (x.bookings / maxTrend) * 100)}%` }} title={`${x.bookings} bookings`} data-testid={`bar-bookings-${i}`} /><span className="font-mono-ui text-[9px] text-muted-foreground">{x.day}</span></div>)}</div></div><div className="card p-5"><p className="eyebrow">Crop mix</p><h2 className="mt-1 text-lg font-bold">Quantity by crop</h2><div className="mt-6 space-y-5">{d.cropMix.map((x, i) => <div key={x.crop} data-testid={`crop-mix-${x.crop}`}><div className="flex justify-between text-sm"><span className="font-bold">{x.crop}</span><span className="font-mono-ui text-xs text-muted-foreground">{x.quantity} qtl</span></div><div className="mt-2 progress-track"><div className={`progress-fill ${i === 1 ? 'bg-accent' : ''}`} style={{ width: `${totalCrop ? (x.quantity / totalCrop) * 100 : 0}` }} /></div></div>)}</div><div className="mt-7 rounded-xl bg-secondary/60 p-4"><p className="eyebrow">Total procurement</p><p className="mt-1 text-2xl font-bold">{d.totalQuantity} qtl</p><p className="mt-1 text-xs text-muted-foreground">Recorded across the network this season.</p></div></div></div></main>;
}

function NotFound() { return <main className="grid min-h-[100dvh] place-items-center p-5"><div className="text-center"><p className="eyebrow">404 · off the map</p><h1 className="mt-3 text-4xl font-bold">This field is empty.</h1><Link href="/dashboard" className="btn btn-primary mt-6" data-testid="link-return-dashboard">Back to overview</Link></div></main>; }

function Router() {
  const [location, setLocation] = useLocation();
  const [role, setRole] = useState<Role | null>(() => sessionStorage.getItem('sf_role') as Role | null);
  const signOut = () => { sessionStorage.removeItem('sf_role'); setRole(null); setLocation('/'); };
  if (!role || location === '/') return <Landing onLogin={setRole} />;
  const routePage = <Switch><Route path="/dashboard" component={DashboardPage} /><Route path="/bookings" component={BookingsPage} /><Route path="/bookings/new" component={NewBookingPage} /><Route path="/centres" component={CentresPage} /><Route path="/payments" component={PaymentsPage} /><Route path="/profile" component={ProfilePage} /><Route path="/officer" component={OfficerPage} /><Route path="/admin" component={AdminPage} /><Route component={NotFound} /></Switch>;
  return <Shell role={role} onSignOut={signOut}>{routePage}</Shell>;
}

function App() {
  return <QueryClientProvider client={queryClient}><TooltipProvider><ErrorBoundary resetKey={window.location.pathname}><Router /></ErrorBoundary><Toaster /></TooltipProvider></QueryClientProvider>;
}

export default App;